using Microsoft.EntityFrameworkCore;using System.Net.Http.Json;using System.Globalization;using System.Text.Json;
namespace DaNgoai;
public class ChuyenDi{public int MaChuyen{get;set;}public string TenChuyen{get;set;}="";public string DiaDiem{get;set;}="";public DateTime NgayDi{get;set;}public int SoNguoi{get;set;}public decimal NganSach{get;set;}public string PhuongTien{get;set;}="";public bool DaHoanThanh{get;set;}public string? GhiChu{get;set;}}
public class TripContext(string cs):DbContext{public DbSet<ChuyenDi> ChuyenDis=>Set<ChuyenDi>();protected override void OnConfiguring(DbContextOptionsBuilder b)=>b.UseSqlServer(cs);protected override void OnModelCreating(ModelBuilder b){b.Entity<ChuyenDi>().ToTable("ChuyenDi").HasKey(x=>x.MaChuyen);b.Entity<ChuyenDi>().Property(x=>x.NganSach).HasColumnType("decimal(18,0)");}}
public sealed class MainForm:Form{static readonly HttpClient http=new(){Timeout=TimeSpan.FromSeconds(8)};readonly TripContext db;readonly TextBox title=new(){Width=140},place=new(){Width=140},search=new(){Width=130};readonly DateTimePicker date=new(){Format=DateTimePickerFormat.Short};readonly NumericUpDown people=new(){Minimum=1,Maximum=100},budget=new(){Maximum=1000000000,Increment=100000};readonly ComboBox transport=new(){DropDownStyle=ComboBoxStyle.DropDownList};readonly CheckBox done=new(){Text="Đã hoàn thành"},unfinished=new(){Text="Chỉ chưa hoàn thành"};readonly DateTimePicker from=new(){Format=DateTimePickerFormat.Short},to=new(){Format=DateTimePickerFormat.Short};readonly DataGridView grid=new(){Dock=DockStyle.Fill,ReadOnly=true,AutoGenerateColumns=true,SelectionMode=DataGridViewSelectionMode.FullRowSelect};readonly Label weather=new(){AutoSize=true,Font=new Font("Segoe UI",12,FontStyle.Bold)};readonly ProgressBar progress=new(){Style=ProgressBarStyle.Marquee,Visible=false,Width=150};readonly ComboBox lang=new(){DropDownStyle=ComboBoxStyle.DropDownList};int id;string Language="vi";public MainForm(string cs){db=new(cs);Width=1100;Height=700;Text="Kế hoạch dã ngoại";transport.Items.AddRange(["Xe máy","Ô tô","Xe khách","Tàu hỏa"]);lang.Items.AddRange(["Tiếng Việt","English"]);lang.SelectedIndex=0;var p=new FlowLayoutPanel{Dock=DockStyle.Top,Height=150};p.Controls.AddRange([new Label{Text="Tên chuyến"},title,new Label{Text="Địa điểm"},place,new Label{Text="Ngày đi"},date,new Label{Text="Người"},people,new Label{Text="Ngân sách"},budget,transport,done]);foreach(var (t,a) in new (string,Action)[]{("Thêm",Add),("Sửa",Edit),("Xóa",Delete),("Làm mới",Clear),("Xem thời tiết",async()=>await Weather())}){var b=new Button{Text=t};b.Click+=async(_,_)=>a();p.Controls.Add(b);}p.Controls.AddRange([search,unfinished,from,to,lang,progress]);Controls.Add(grid);Controls.Add(weather);Controls.Add(p);Load+=(_,_)=>{var path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DaNgoai","usersettings.json");try{if(File.Exists(path)&&File.ReadAllText(path).Contains("en")){lang.SelectedIndex=1;Language="en";}}catch{}LoadGrid();};lang.SelectedIndexChanged+=(_,_)=>{Language=lang.SelectedIndex==1?"en":"vi";Directory.CreateDirectory(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DaNgoai"));File.WriteAllText(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DaNgoai","usersettings.json"),JsonSerializer.Serialize(new{language=Language}));};foreach(Control c in new Control[]{search,unfinished,from,to}){if(c is TextBox t)t.TextChanged+=(_,_)=>LoadGrid();else if(c is CheckBox k)k.CheckedChanged+=(_,_)=>LoadGrid();else if(c is DateTimePicker d)d.ValueChanged+=(_,_)=>LoadGrid();}grid.SelectionChanged+=(_,_)=>{if(grid.CurrentRow?.DataBoundItem is ChuyenDi x){id=x.MaChuyen;title.Text=x.TenChuyen;place.Text=x.DiaDiem;date.Value=x.NgayDi;people.Value=x.SoNguoi;budget.Value=Math.Clamp(x.NganSach,0,budget.Maximum);transport.Text=x.PhuongTien;done.Checked=x.DaHoanThanh;}};}
void LoadGrid(){try{var q=db.ChuyenDis.AsNoTracking().AsQueryable();if(search.Text!=""){var s=search.Text.Trim();q=q.Where(x=>x.TenChuyen.Contains(s)||x.DiaDiem.Contains(s));}if(unfinished.Checked)q=q.Where(x=>!x.DaHoanThanh);var a=from.Value.Date;var b=to.Value.Date;if(a>b){a=DateTime.MinValue;b=DateTime.MaxValue;}q=q.Where(x=>x.NgayDi>=a&&x.NgayDi<=b);grid.DataSource=q.OrderBy(x=>x.NgayDi).ToList();}catch(Exception e){Serilog.Log.Error(e,"Load trips");}}
ChuyenDi Entry()=>new(){TenChuyen=title.Text.Trim(),DiaDiem=place.Text.Trim(),NgayDi=date.Value.Date,SoNguoi=(int)people.Value,NganSach=budget.Value,PhuongTien=transport.Text,DaHoanThanh=done.Checked};void Add(){var x=Entry();if(x.TenChuyen==""||x.DiaDiem==""||x.NgayDi<DateTime.Today){MessageBox.Show("Cần nhập tên, địa điểm và ngày đi từ hôm nay trở đi.");return;}db.Add(x);db.SaveChanges();LoadGrid();}void Edit(){if(id==0)return;var x=db.Find<ChuyenDi>(id);if(x==null)return;var a=Entry();x.TenChuyen=a.TenChuyen;x.DiaDiem=a.DiaDiem;x.NgayDi=a.NgayDi;x.SoNguoi=a.SoNguoi;x.NganSach=a.NganSach;x.PhuongTien=a.PhuongTien;x.DaHoanThanh=a.DaHoanThanh;db.SaveChanges();LoadGrid();}void Delete(){if(id==0)return;db.Remove(db.Find<ChuyenDi>(id)!);db.SaveChanges();LoadGrid();}void Clear(){id=0;title.Clear();place.Clear();date.Value=DateTime.Today;people.Value=1;budget.Value=0;done.Checked=false;}
async Task Weather(){if(grid.CurrentRow?.DataBoundItem is not ChuyenDi x)return;progress.Visible=true;try{var g=await http.GetFromJsonAsync<Geo>($"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(x.DiaDiem)}&count=1&language=vi");if(g?.results?.FirstOrDefault() is not { } loc){weather.Text=Language=="en"?"Place not found; try an unaccented name":"Không tìm thấy địa danh; thử tên không dấu";return;}var w=await http.GetFromJsonAsync<Forecast>($"https://api.open-meteo.com/v1/forecast?latitude={loc.latitude}&longitude={loc.longitude}&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max&timezone=auto&forecast_days=16");int i=w?.daily?.time?.IndexOf(x.NgayDi.ToString("yyyy-MM-dd"))??-1;if(i<0){weather.Text=Language=="en"?"Forecast unavailable":"Chưa có dữ liệu dự báo";return;}int rain=w!.daily!.precipitation_probability_max![i];var desc=Language=="en"?"Forecast":"Dự báo";weather.Text=$"{desc}: {w.daily.weather_code![i]} | {w.daily.temperature_2m_min![i]}–{w.daily.temperature_2m_max![i]} °C | {rain}%"+(rain>=60?(Language=="en"?" - Bring raincoat or reschedule":" - Nên mang áo mưa hoặc cân nhắc dời lịch"):"");weather.BackColor=rain>=60?Color.Orange:Color.LightGreen;}catch(Exception e){Serilog.Log.Warning(e,"Weather request failed");weather.Text=Language=="en"?"Network error":"Lỗi mạng khi tải thời tiết";}finally{progress.Visible=false;}}record Geo(List<Loc>? results);record Loc(double latitude,double longitude);record Forecast(Daily? daily);record Daily(List<string>? time,List<int>? weather_code,List<double>? temperature_2m_max,List<double>? temperature_2m_min,List<int>? precipitation_probability_max);}
